{
 "additionalProperties": false,
 "properties": {
  "actions": {
   "default": [],
   "items": {
    "$ref": "#/components/schemas/Kibana_HTTP_APIs_new_rule_action"
   },
   "type": "array"
  },
  "alert_delay": {
   "additionalProperties": false,
   "description": "Indicates that an alert occurs only when the specified number of consecutive runs met the rule conditions.",
   "type": "object",
   "properties": {
    "active": {
     "description": "The number of consecutive runs that must meet the rule conditions.",
     "type": "number"
    }
   },
   "required": [
    "active"
   ]
  },
  "artifacts": {
   "additionalProperties": false,
   "type": "object",
   "properties": {
    "dashboards": {
     "items": {
      "additionalProperties": false,
      "type": "object",
      "properties": {
       "id": {
        "type": "string"
       }
      },
      "required": [
       "id"
      ]
     },
     "maxItems": 10,
     "type": "array"
    },
    "investigation_guide": {
     "additionalProperties": false,
     "type": "object",
     "properties": {
      "blob": {
       "maxLength": 10000,
       "type": "string"
      }
     },
     "required": [
      "blob"
     ]
    }
   }
  },
  "consumer": {
   "description": "The name of the application or feature that owns the rule. For example: `alerts`, `apm`, `discover`, `infrastructure`, `logs`, `metrics`, `ml`, `monitoring`, `securitySolution`, `siem`, `stackAlerts`, or `uptime`.",
   "type": "string"
  },
  "enabled": {
   "default": true,
   "description": "Indicates whether you want the rule to run on an interval basis after it is created.",
   "type": "boolean"
  },
  "flapping": {
   "allOf": [
    {
     "$ref": "#/components/schemas/Kibana_HTTP_APIs_rule_flapping"
    }
   ],
   "nullable": true
  },
  "name": {
   "description": "The name of the rule. While this name does not have to be unique, a distinctive name can help you identify a rule.",
   "type": "string"
  },
  "notify_when": {
   "description": "Indicates how frequently rule actions are triggered. Valid values include: `onActionGroupChange`: Actions run when the alert status changes; `onActiveAlert`: Actions run when the alert becomes active and at each check interval while the rule conditions are met; `onThrottleInterval`: Actions run when the alert becomes active and at the interval specified in the throttle property while the rule conditions are met. You cannot specify `notify_when` at both the rule and action level. The recommended approach is to set it for each action individually. If you set `notify_when` at the rule level and then edit the rule, it will automatically be converted to action-specific values.",
   "enum": [
    "onActionGroupChange",
    "onActiveAlert",
    "onThrottleInterval",
    null
   ],
   "nullable": true,
   "type": "string"
  },
  "params": {
   "additionalProperties": false,
   "description": "The parameters for the ES query rule. These parameters are appropriate when `rule_type_id` is `.es-query`.",
   "properties": {
    "aggField": {
     "description": "The name of the numeric field that is used in the aggregation. This property is required when `aggType` is `avg`, `max`, `min` or `sum`.",
     "minLength": 1,
     "type": "string"
    },
    "aggType": {
     "default": "count",
     "description": "The type of aggregation to perform.",
     "type": "string"
    },
    "esqlQuery": {
     "anyOf": [
      {
       "items": {},
       "type": "array"
      },
      {
       "type": "boolean"
      },
      {
       "type": "number"
      },
      {
       "type": "object"
      },
      {
       "type": "string"
      }
     ],
     "description": "The query definition in Elasticsearch Query Language.",
     "nullable": true,
     "oneOf": [
      {
       "additionalProperties": false,
       "type": "object",
       "properties": {
        "esql": {
         "minLength": 1,
         "type": "string"
        }
       },
       "required": [
        "esql"
       ]
      },
      {
       "not": {}
      }
     ]
    },
    "esQuery": {
     "anyOf": [
      {
       "items": {},
       "type": "array"
      },
      {
       "type": "boolean"
      },
      {
       "type": "number"
      },
      {
       "type": "object"
      },
      {
       "type": "string"
      }
     ],
     "nullable": true,
     "oneOf": [
      {
       "minLength": 1,
       "type": "string"
      },
      {
       "not": {}
      }
     ]
    },
    "excludeHitsFromPreviousRun": {
     "default": true,
     "description": "Indicates whether to exclude matches from previous runs. If `true`, you can avoid alert duplication by excluding documents that have already been detected by the previous rule run. This option is not available when a grouping field is specified.",
     "type": "boolean"
    },
    "groupBy": {
     "default": "all",
     "description": "Indicates whether the aggregation is applied over all documents (`all`), grouped by row (`row`), or split into groups (`top`) using a grouping field (`termField`) where only the top groups (up to `termSize` number of groups) are checked. If grouping is used, an alert will be created for each group when it exceeds the threshold.",
     "type": "string"
    },
    "index": {
     "anyOf": [
      {
       "items": {},
       "type": "array"
      },
      {
       "type": "boolean"
      },
      {
       "type": "number"
      },
      {
       "type": "object"
      },
      {
       "type": "string"
      }
     ],
     "description": "The indices to query.",
     "nullable": true,
     "oneOf": [
      {
       "items": {
        "minLength": 1,
        "type": "string"
       },
       "minItems": 1,
       "type": "array"
      },
      {
       "not": {}
      }
     ]
    },
    "searchConfiguration": {
     "anyOf": [
      {
       "items": {},
       "type": "array"
      },
      {
       "type": "boolean"
      },
      {
       "type": "number"
      },
      {
       "type": "object"

